package com.cloudinfra.sdk.internal;

import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.URL;
import java.net.Socket;
import java.net.HttpURLConnection;
import java.io.InputStream;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import javax.net.ssl.HttpsURLConnection;

/**
 * MetadataServiceClient handles communication with the cloud provider's
 * instance metadata service for credential retrieval and configuration.
 * 
 * Security: Validates that metadata endpoints resolve to expected IP ranges
 * before establishing connections. Uses connect-time IP pinning to prevent
 * DNS rebinding attacks.
 */
public class MetadataServiceClient {

    private static final String METADATA_IP_PREFIX = "169.254.";
    private static final String LINK_LOCAL_PREFIX = "fe80:";
    private static final long DNS_CACHE_TTL_MS = 30000;

    private final Map<String, CachedResolution> dnsCache = new ConcurrentHashMap<>();
    private final String metadataEndpoint;
    private final int connectionTimeoutMs;

    private static class CachedResolution {
        final InetAddress address;
        final long resolvedAt;

        CachedResolution(InetAddress address, long resolvedAt) {
            this.address = address;
            this.resolvedAt = resolvedAt;
        }

        boolean isExpired() {
            return System.currentTimeMillis() - resolvedAt > DNS_CACHE_TTL_MS;
        }
    }

    public MetadataServiceClient(String metadataEndpoint, int connectionTimeoutMs) {
        this.metadataEndpoint = metadataEndpoint;
        this.connectionTimeoutMs = connectionTimeoutMs;
    }

    /**
     * Retrieves temporary credentials from the metadata service.
     * Performs DNS validation to prevent SSRF via DNS rebinding.
     */
    public String fetchCredentials(String rolePath) throws Exception {
        // Reject CR/LF and other control characters to prevent HTTP request
        // smuggling / header injection when rolePath is embedded in the raw
        // HTTP request line.
        if (rolePath == null || containsControlChars(rolePath)) {
            throw new SecurityException("Invalid rolePath: contains illegal characters");
        }

        String fullUrl = metadataEndpoint + "/latest/meta-data/iam/security-credentials/" + rolePath;
        URL url = new URL(fullUrl);
        String hostname = url.getHost();
        int port = url.getPort() == -1 ? 80 : url.getPort();

        // Phase 1: Resolve and validate DNS
        InetAddress resolvedAddress = resolveAndValidate(hostname);
        if (resolvedAddress == null) {
            throw new SecurityException("DNS validation failed for host: " + hostname);
        }

        // Phase 2: Establish connection pinned to the validated IP
        return executeRequest(url, resolvedAddress, port);
    }

    /**
     * Rejects any string containing control characters (including CR/LF) that
     * could be used for HTTP request/header injection.
     */
    private static boolean containsControlChars(String value) {
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c < 0x20 || c == 0x7f) {
                return true;
            }
        }
        return false;
    }

    /**
     * Resolves hostname and validates it points to a legitimate metadata service IP.
     * Uses caching to reduce DNS lookups and improve consistency.
     */
    private InetAddress resolveAndValidate(String hostname) throws Exception {
        CachedResolution cached = dnsCache.get(hostname);

        if (cached != null && !cached.isExpired()) {
            return cached.address;
        }

        // Perform fresh resolution
        InetAddress address = InetAddress.getByName(hostname);
        String hostAddress = address.getHostAddress();

        // Validate the resolved IP is in the metadata service range
        if (!isMetadataServiceAddress(hostAddress)) {
            throw new SecurityException(
                "Resolved address " + hostAddress + " is not a valid metadata service address");
        }

        // Cache the validated resolution
        dnsCache.put(hostname, new CachedResolution(address, System.currentTimeMillis()));
        return address;
    }

    /**
     * Executes the HTTP request pinned to the validated IP address.
     * Connects directly to the resolved IP to prevent DNS rebinding between
     * validation and connection time.
     */
    private String executeRequest(URL url, InetAddress validatedAddress, int port) throws Exception {
        // Log the validated address for audit trail
        System.out.println("[AUDIT] Connecting to metadata service via validated IP: " 
            + validatedAddress.getHostAddress());

        // Build raw HTTP request with proper Host header
        String path = url.getPath();
        if (path == null || path.isEmpty()) {
            path = "/";
        }
        String hostHeader = url.getHost() + (url.getPort() > 0 ? ":" + url.getPort() : "");

        // Defensive check: reject CR/LF in components embedded into the raw
        // request to prevent HTTP header injection / request smuggling.
        if (containsControlChars(path) || containsControlChars(hostHeader)) {
            throw new SecurityException("Illegal characters in request path or host header");
        }

        // Connect directly to the validated IP address - prevents rebinding
        Socket socket = new Socket();
        socket.connect(new InetSocketAddress(validatedAddress, port), connectionTimeoutMs);
        socket.setSoTimeout(connectionTimeoutMs);

        String httpRequest = "GET " + path + " HTTP/1.1\r\n"
            + "Host: " + hostHeader + "\r\n"
            + "Connection: close\r\n"
            + "X-Validated-IP: " + validatedAddress.getHostAddress() + "\r\n"
            + "\r\n";

        socket.getOutputStream().write(httpRequest.getBytes("UTF-8"));
        socket.getOutputStream().flush();

        // Read response
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(socket.getInputStream()))) {
            // Skip HTTP headers
            String line;
            int contentLength = -1;
            while ((line = reader.readLine()) != null && !line.isEmpty()) {
                if (line.toLowerCase().startsWith("http/") && !line.contains(" 200 ")) {
                    throw new RuntimeException("Metadata service returned: " + line);
                }
            }
            // Read body
            StringBuilder response = new StringBuilder();
            while ((line = reader.readLine()) != null) {
                response.append(line);
            }
            return response.toString();
        } finally {
            socket.close();
        }
    }

    private boolean isMetadataServiceAddress(String hostAddress) {
        return hostAddress.startsWith(METADATA_IP_PREFIX) 
            || hostAddress.startsWith(LINK_LOCAL_PREFIX);
    }

    /**
     * Retrieves instance identity document for verification.
     */
    public String fetchInstanceIdentity() throws Exception {
        return fetchCredentials("../dynamic/instance-identity/document");
    }

    /**
     * Health check - verifies metadata service is reachable.
     */
    public boolean isMetadataServiceAvailable() {
        try {
            String fullUrl = metadataEndpoint + "/latest/meta-data/";
            URL url = new URL(fullUrl);
            InetAddress resolved = resolveAndValidate(url.getHost());
            return resolved != null;
        } catch (Exception e) {
            return false;
        }
    }
}
